## Putting it into your audit script

Below is a more complete example that also records *why* a layer was (or wasn’t) classified as a shield. This can be useful for debugging false‑positives/negatives.

```js
function classifyShield(layer) {
  const reasons = [];

  if (layer.type !== 'symbol') {
    reasons.push('not a symbol layer');
    return {isShield: false, reasons};
  }

  const layout = layer.layout || {};

  // ---- icon‑image -------------------------------------------------
  const iconImg = layout['icon-image'];
  if (!iconImg) {
    reasons.push('missing icon-image');
    return {isShield: false, reasons};
  }

  const isString = typeof iconImg === 'string';
  const hasBraces = isString && iconImg.includes('{') && iconImg.includes('}');
  if (!hasBraces) {
    reasons.push('icon-image not tokenised');
  }

  const shieldTokens = ['{network}', '{ref}', '{ref_length}'];
  const tokenMatch = shieldTokens.some(tok => iconImg && iconImg.includes(tok));
  if (!tokenMatch) {
    reasons.push('icon-image does not contain shield tokens');
  }

  // ---- text‑field ------------------------------------------------
  const textField = layout['text-field'];
  if (!textField) {
    reasons.push('missing text-field');
  } else {
    const tfString = typeof textField === 'string' ? textField : JSON.stringify(textField);
    if (!tfString.includes('{ref}') && !tfString.includes('["get","ref"]')) {
      reasons.push('text-field does not reference ref');
    }
  }

  // ---- optional stretchable‑badge check -------------------------
  const textFit = layout['icon-text-fit'];
  const stretchable = textFit && textFit !== 'none';

  // ---- final decision --------------------------------------------
  const isShield = hasBraces && tokenMatch && textField && (stretchable || true);
  if (!isShield) reasons.push('failed required shield criteria');

  return {isShield, reasons};
}

// Example usage:
style.layers.forEach(l => {
  const {isShield, reasons} = classifyShield(l);
  if (isShield) console.log(`🔰 Shield layer: ${l.id}`);
  else if (reasons.length) console.debug(`❌ ${l.id}: ${reasons.join('; ')}`);
});
```

You can adapt the `shieldTokens` array or add extra checks (e.g., `metadata.shield === true`) depending on the particular style you are auditing.

---

## TL;DR Summary for Your Script

* **Drop the `text-anchor` / `symbol-placement === "point"` test.**  
* **Add a test that the layer has both `icon-image` *and* `text-field`.
